import{_ as u,a0 as a,w as r,s as l,ao as s,I as p,x as n,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const G=JSON.parse('{"title":"英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步 | LCTT x X-CMD","titleTemplate":false,"description":"英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220512 NVIDIA Takes a Big Step to Improve its GPU Experience on Linux","title":"英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步","tag":"202205","desc":""},"relativePath":"202205/20220512 NVIDIA Takes a Big Step to Improve its GPU Experience on Linux.md","filePath":"[post].md"}'),d={name:"202205/20220512 NVIDIA Takes a Big Step to Improve its GPU Experience on Linux.md"};function x(m,t,f,T,v,P){const e=a("Link");return r(),l("div",null,[t[23]||(t[23]=s('<h1 id="英伟达在提升-linux-上的-gpu-使用体验上迈出了一大步" tabindex="-1">英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步 <a class="header-anchor" href="#英伟达在提升-linux-上的-gpu-使用体验上迈出了一大步" aria-label="Permalink to “英伟达在提升 Linux 上的 GPU 使用体验上迈出了一大步”">​</a></h1><blockquote><p>英伟达公司提升其 GPU 在 Linux 上的体验的重大开源计划终于来了。</p></blockquote><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/05/linus-torvalds-nvidia.jpg" alt=""></p><p>Linus Torvalds 听到这个消息一定会很高兴……</p><p>英伟达终于公布了提升 Linux 上的 GPU 使用体验的开源计划。</p><p>不过不幸的是，和你想象的可能不完全一样，你仍然会看到一些专有的驱动程序。</p><p>但是，它的意义不亚于甩掉专有驱动程序。</p><p>具体来说就是，<strong>英伟达发布了开源的 GPU 内核模块，支持数据中心所用的 GPU 和消费级显卡（GeForce/RTX）</strong>。</p><p>此外，它同时采用 GPL/MIT 两种许可证，听起来很棒，对吗？</p><h3 id="此举对-linux-桌面用户有什么帮助" tabindex="-1">此举对 Linux 桌面用户有什么帮助？ <a class="header-anchor" href="#此举对-linux-桌面用户有什么帮助" aria-label="Permalink to “此举对 Linux 桌面用户有什么帮助？”">​</a></h3><p>开源的 GPU 内核模块有助于改善内核和专有驱动程序之间的交互。</p><p>所以，此举对 <strong>游戏玩家和开发者</strong> 都有利，阻碍与英伟达专有驱动程序配合的问题最终会被消除。</p><p>发布公告中提到的技术收益包括：</p><blockquote><p>开发者可以跟踪到具体的代码路径，并观察到内核事件调度是如何与他们的工作负载交互的，从而在调试时更快定位根本原因。此外，企业软件开发者可以将该驱动程序无缝地集成到他们为项目定制的 Linux 内核中。</p><p>来自 Linux 最终用户社区的投入和评价，将进一步提升英伟达 GPU 驱动程序的质量和安全性。</p></blockquote><p>而从最终用户或者游戏玩家方面来看，你会发现安装将更便捷，整体会更安全。</p><p>Canonical 和 SUSE 会立即为他们的企业用户打包该开源内核模块，而其它厂商也会很快跟进。</p><p>当它可以用在桌面环境时，Canonical 应该会在未来几个月内把这个内核模块放到 Ubuntu 22.04 LTS 版本中。其它的 Linux 发行版应该也会做相应的升级。</p><h3 id="现在可以试用吗" tabindex="-1">现在可以试用吗？ <a class="header-anchor" href="#现在可以试用吗" aria-label="Permalink to “现在可以试用吗？”">​</a></h3><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/05/nvidia-opensource-linux-drivers-1024x576.jpg" alt=""></p><p>这个开源的 GPU 内核模块的第一个版本是 R515，它是作为 CUDA 工具集 11.7 一部分一起发布的开发驱动程序。</p>',20)),p("p",null,[t[2]||(t[2]=n("你可以从 ",-1)),i(e,{href:"https://www.nvidia.com/en-us/drivers/unix/"},{default:o(()=>[...t[0]||(t[0]=[n("官方驱动下载页面",-1)])]),_:1}),t[3]||(t[3]=n(" 或者从 ",-1)),i(e,{href:"https://developer.nvidia.com/cuda-downloads"},{default:o(()=>[...t[1]||(t[1]=[n("CUDA 下载页面",-1)])]),_:1}),t[4]||(t[4]=n(" 找到。",-1))]),t[24]||(t[24]=s('<p>虽然它被认为可用于数据中心生产环境，<strong>但对于 GeForce 或者工作站 GPU 来说，还处于 alpha 阶段</strong>。</p><p>事实上，在 Turing 和 Ampere 架构的 GPU 型号上可以使用这个驱动程序，以使用 Vulkan 和 Optix 中的 <strong>多显示器、G-Sync、Nvidia RTX 光线追踪</strong> 等功能。</p><p>然而，除非你想运行一些“实验性测试”，否则还是等几个月，以便直接从你的 Linux 发行版中获得为桌面用户发布的稳定版。</p><h3 id="对-nouveau-驱动程序开发也有益" tabindex="-1">对 Nouveau 驱动程序开发也有益 <a class="header-anchor" href="#对-nouveau-驱动程序开发也有益" aria-label="Permalink to “对 Nouveau 驱动程序开发也有益”">​</a></h3><p>不仅仅是提升了专有驱动程序的体验，公布的这个开源 GPU 内核代码也会改善 Nouveau 驱动。</p><p>正如发布公告所说：</p><blockquote><p>Nouveau 可以利用英伟达驱动程序所使用的同样固件，它公开了许多 GPU 功能，例如时钟管理、散热管理，可以为树内的 Nouveau 驱动程序带来新的特性。</p><p>请关注未来的驱动更新以及在 Github 上的合作。</p></blockquote><p>英伟达公司提到并可能合作改进开源的英伟达驱动程序（即 Nouveau），这真是太好了。</p><p>这也很好地表明了，他们确实希望为 Linux 提供一个更好的开源驱动程序版本。</p><h3 id="开源-nivida-驱动程序的未来" tabindex="-1">开源 Nivida 驱动程序的未来？ <a class="header-anchor" href="#开源-nivida-驱动程序的未来" aria-label="Permalink to “开源 Nivida 驱动程序的未来？”">​</a></h3><p>毋容置疑，英伟达计划不断发布开源的 GPU 内核模块。</p><p>所以，尽管他们不会单独开源他们的驱动程序，但我们仍然可以寄希望于 Nouveau 释放所有的显卡特性。</p>',12)),p("p",null,[t[6]||(t[6]=n("想知道他们更多的计划，你可以参考 ",-1)),i(e,{href:"https://developer.nvidia.com/blog/nvidia-releases-open-source-gpu-kernel-modules/"},{default:o(()=>[...t[5]||(t[5]=[n("官方的发布声明",-1)])]),_:1}),t[7]||(t[7]=n("。",-1))]),t[25]||(t[25]=p("p",null,[p("em",null,"你如何看待这件事？英伟达最终会爱开源和 Linux 吗？嗯，至少这是一个好的开始。在下面的评论区分享你的想法吧。")],-1)),t[26]||(t[26]=p("hr",null,null,-1)),p("p",null,[t[9]||(t[9]=n("via: ",-1)),i(e,{href:"https://news.itsfoss.com/nvidia-open-source-linux/"},{default:o(()=>[...t[8]||(t[8]=[n("https://news.itsfoss.com/nvidia-open-source-linux/",-1)])]),_:1})]),p("p",null,[t[14]||(t[14]=n("作者：",-1)),i(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...t[10]||(t[10]=[n("Ankush Das",-1)])]),_:1}),t[15]||(t[15]=n(" 选题：",-1)),i(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[11]||(t[11]=[n("lkxed",-1)])]),_:1}),t[16]||(t[16]=n(" 译者：",-1)),i(e,{href:"https://github.com/chunyang-wen"},{default:o(()=>[...t[12]||(t[12]=[n("chunyang-wen",-1)])]),_:1}),t[17]||(t[17]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[20]||(t[20]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[n("LCTT",-1)])]),_:1}),t[21]||(t[21]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[n("Linux中国",-1)])]),_:1}),t[22]||(t[22]=n(" 荣誉推出",-1))])])}const U=u(d,[["render",x]]);export{G as __pageData,U as default};
